#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum CardType {
    Master,
    Action,
    ActionModifier,
    Reaction,
    Combat,
    PoliticalAction,
    Ally,
    Equipment,
    Retainer,
    Event,
    Power,
    Conviction,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Cost {
    None,
    Fixed(u8),
    /// Printed "X": chosen when the card is played.
    X,
}

/// Printed labels the rules key on (uniqueness, one hunting ground per
/// turn, one vehicle, one archetype, trifle accounting, …).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
